<?php
namespace App\Console\Commands;use App\Jobs\RunScheduledAgentJob;use App\Models\AgentSchedule;use Cron\CronExpression;use Illuminate\Console\Command;
class DispatchDueSchedules extends Command {protected $signature='enverif:schedules:due';protected $description='Dispatch due Enverif agent schedules.';public function handle():int{$count=0;AgentSchedule::withoutGlobalScopes()->where('enabled',true)->where(fn($q)=>$q->whereNull('next_run_at')->orWhere('next_run_at','<=',now()))->orderBy('id')->chunkById(100,function($schedules)use(&$count){foreach($schedules as $schedule){$cron=new CronExpression($schedule->cron_expression);$next=$cron->getNextRunDate('now',0,false,$schedule->timezone);$updated=AgentSchedule::withoutGlobalScopes()->whereKey($schedule->id)->where(fn($q)=>$q->whereNull('next_run_at')->orWhere('next_run_at','<=',now()))->update(['next_run_at'=>$next]);if($updated===1){RunScheduledAgentJob::dispatch($schedule->id);$count++;}}});$this->info("Dispatched {$count} due schedule(s).");return self::SUCCESS;}}
